# 输入验证
def get_positive_number():
    while True:
        try:
            num = int(input("请输入正数："))
            if num <= 0:
                raise ValueError("必须输入正数")
            return num
        except ValueError as e:
            print(f"输入错误：{e}")

# 自定义异常
class ValidationError(Exception):
    def __init__(self, message, field):
        self.message = message
        self.field = field

def validate_user(username, age):
    if not username:
        raise ValidationError("用户名不能为空", "username")
    if age < 0:
        raise ValidationError("年龄不能为负", "age")

